  });

  it('rejects a booking shorter than 30 minutes', async () => {
    const response = await app.inject({
      method: 'POST',
      url: '/bookings',
      payload: {
        roomId,
        userId,
        title: 'Too short',
        startsAt: inHours(24),
        endsAt: new Date(Date.now() + 24 * HOUR + 10 * 60_000).toISOString(),
      },
    });
    expect(response.statusCode).toBe(400);
  });

  it('rejects a booking longer than 8 hours', async () => {
    const response = await book(24, 24 + 8.5, 'Marathon');
    expect(response.statusCode).toBe(400);
  });

  it('accepts a booking exactly 30 minutes long', async () => {
    const response = await app.inject({
      method: 'POST',
      url: '/bookings',
      payload: {
        roomId,
        userId,
        title: 'Quick sync',
        startsAt: inHours(24),
        endsAt: new Date(Date.now() + 24 * HOUR + 30 * 60_000).toISOString(),
      },
    });
    expect(response.statusCode).toBe(201);
  });

  it('accepts a booking exactly 8 hours long', async () => {
    const response = await book(24, 32, 'All day');
    expect(response.statusCode).toBe(201);
  });

  it('rejects a booking for a room that does not exist', async () => {
    const response = await app.inject({
      method: 'POST',
      url: '/bookings',
      payload: { roomId: 'missing', userId, title: 'Sync', startsAt: inHours(24), endsAt: inHours(25) },
    });
    expect(response.statusCode).toBe(404);
  });

  it('rejects a booking for a user that does not exist', async () => {
    const response = await app.inject({
      method: 'POST',
      url: '/bookings',
      payload: { roomId, userId: 'missing', title: 'Sync', startsAt: inHours(24), endsAt: inHours(25) },
    });
    expect(response.statusCode).toBe(404);
  });

  it('rejects moving a booking on top of another active booking', async () => {
    await book(24, 25);
    const second = await book(30, 31, 'Movable');
    const response = await app.inject({
      method: 'PATCH',
      url: `/bookings/${second.json().id}`,
      payload: { startsAt: inHours(24.5), endsAt: inHours(25.5) },
    });
    expect(response.statusCode).toBe(409);
  });

  it('rejects moving a booking to a room that does not exist', async () => {
    const created = await book(24, 25);
    const response = await app.inject({
      method: 'PATCH',
      url: `/bookings/${created.json().id}`,
      payload: { roomId: 'missing' },
    });
    expect(response.statusCode).toBe(404);
  });

  it('rejects moving a booking to a user that does not exist', async () => {
    const created = await book(24, 25);
    const response = await app.inject({
      method: 'PATCH',
      url: `/bookings/${created.json().id}`,
      payload: { userId: 'missing' },
    });
    expect(response.statusCode).toBe(404);
  });

  it('rejects stretching a booking past the 8 hour limit', async () => {
    const created = await book(24, 25);
    const response = await app.inject({
      method: 'PATCH',
      url: `/bookings/${created.json().id}`,
      payload: { endsAt: inHours(33) },
    });
    expect(response.statusCode).toBe(400);
  });

  it('allows moving a booking into a slot that does not conflict', async () => {
    await book(24, 25);
    const second = await book(30, 31, 'Movable');
    const response = await app.inject({
      method: 'PATCH',
      url: `/bookings/${second.json().id}`,
      payload: { startsAt: inHours(40), endsAt: inHours(41) },
    });
    expect(response.statusCode).toBe(200);
  });
